import { Link } from 'react-router-dom'

import {
  FitnessCenter,
  FolderOpen as FolderOpenIcon,
  InfoOutlined as InfoOutlinedIcon,
} from '@mui/icons-material'
import { Button } from '@mui/material'
import type { ButtonProps } from '@mui/material'

import { routes } from '@/routes'
import type { TrainingPlan } from '@/types/database'
import { parseFmUrl } from '@/utils/unit-utils'

const prefetchContents = () => import('@/pages/flash-man/contents')
const prefetchExecutionsNew = () => import('@/pages/executions/new')
const prefetchPlanDetail = () => import('@/pages/plans/detail')

interface PlanExecutionButtonProps {
  plan: TrainingPlan
  size?: ButtonProps['size']
  variant?: ButtonProps['variant']
  showDetailButton?: boolean
}

export function PlanExecutionButton({
  plan,
  size,
  variant,
  showDetailButton,
}: PlanExecutionButtonProps) {
  const fmInfo = parseFmUrl(plan.unit_name)

  if (fmInfo) {
    return (
      <>
        {showDetailButton && (
          <Button
            component={Link}
            to={routes.plans.detail.$path({ id: plan.id }, {})}
            onMouseEnter={prefetchPlanDetail}
            onFocus={prefetchPlanDetail}
            startIcon={<InfoOutlinedIcon />}
            size={size}
            variant="outlined"
          >
            상세
          </Button>
        )}
        <Button
          component={Link}
          to={routes.flashMan.contents.$({
            owner: fmInfo.owner,
            repo: fmInfo.repo,
            path: fmInfo.path,
          })}
          onMouseEnter={prefetchContents}
          onFocus={prefetchContents}
          startIcon={<FolderOpenIcon />}
          size={size}
          variant={variant}
        >
          폴더이동
        </Button>
      </>
    )
  }

  return (
    <Button
      component={Link}
      to={routes.executions.new.$({ planId: plan.id })}
      onMouseEnter={prefetchExecutionsNew}
      onFocus={prefetchExecutionsNew}
      startIcon={<FitnessCenter />}
      size={size}
      variant={variant}
    >
      훈련시작
    </Button>
  )
}
